/**
 * Named aliases over the generated OpenAPI schema (`schema.d.ts`, regenerated by
 * `npm run api:types`). Keep this file free of hand-written response shapes: every type that
 * describes an API payload must derive from `components['schemas']` or `paths` so the UI
 * cannot drift from the backend contract.
 */
import type { components, paths } from './schema'

type S = components['schemas']
type Query<P extends keyof paths> = paths[P] extends { get: { parameters: { query?: infer Q } } } ? NonNullable<Q> : never

// ---------------------------------------------------------------------------
// Enums (string-literal unions straight from the contract)
// ---------------------------------------------------------------------------

export type ObjectKind = S['ObjectSummary']['kind']
export type ObjectScope = S['ObjectSummary']['scope']
export type LineageStatus = S['ObjectSummary']['lineage_status']
export type ScanStatus = S['ScanSummary']['status']
export type ScanPhase = S['ScanWarningOut']['phase']
export type EdgeKind = S['LineageEdge']['kind']
export type Resolution = S['LineageEdge']['resolution']
export type Confidence = S['ColumnLineageEdge']['confidence']
export type Transform = S['ColumnLineageEdge']['transform']
export type ColumnKind = S['Column']['column_kind']
export type LineageIssueKind = S['LineageIssue']['kind']
export type LineageDirection = NonNullable<Query<'/api/scans/{scan_id}/lineage/objects'>['direction']>
export type SortOrder = NonNullable<Query<'/api/scans/{scan_id}/objects'>['order']>
export type ObjectSort = NonNullable<Query<'/api/scans/{scan_id}/objects'>['sort']>
export type TableStatsSort = NonNullable<Query<'/api/scans/{scan_id}/stats/tables'>['sort']>
export type IndexStatsSort = NonNullable<Query<'/api/scans/{scan_id}/stats/indexes'>['sort']>
export type ProcStatsSort = NonNullable<Query<'/api/scans/{scan_id}/stats/procs'>['sort']>
export type MissingIndexSort = NonNullable<Query<'/api/scans/{scan_id}/stats/missing-indexes'>['sort']>

// ---------------------------------------------------------------------------
// Envelopes / errors
// ---------------------------------------------------------------------------

export interface Paged<T> {
  items: T[]
  total: number
  limit: number
  offset: number
}

export type ValidationError = S['ValidationError']
export interface ApiErrorDetail {
  detail: string | ValidationError[]
  /** Added by the client middleware (see `api/client.ts`). */
  status?: number
}

// ---------------------------------------------------------------------------
// Connections / config / health
// ---------------------------------------------------------------------------

export type ConnectionDatabase = S['ConnectionDatabase']
export type ConnectionInfo = S['ConnectionInfo']
export type ConnectionList = S['ListEnvelope_ConnectionInfo_']
export type ConnectionTestDatabase = S['ConnectionTestDatabase']
export type ConnectionTestResult = S['ConnectionTestResult']
export type AppConfig = S['ConfigOut']
export type Health = S['Health']

