export type ScanWarning = S['ScanWarningOut']
export type ScanLogEntry = S['ScanLogEntry']
/** `GET /api/scans/{scan_id}` — summary + live progress + warnings. */
export type ScanDetail = S['ScanStatus']
export type StartScanRequest = S['ScanStartRequest']
export type StartScanResponse = S['ScanStarted']
export type ScanCancelled = S['ScanCancelled']
export type SchemaSummary = S['SchemaOverview']
export type DatabaseSummary = S['DatabaseOverview']
export type SnapshotSummary = S['ScanOverview']
export type WarningsSummary = S['WarningsSummary']

