export type ObjectSummary = S['ObjectSummary']
export type ObjectRefLite = S['ObjectRef']
export type ParentRef = S['ParentRef']
export type SearchMatch = S['SearchMatch']
export type SearchObjectHit = S['SearchObjectHit']
export type SearchColumnHit = S['SearchColumnHit']
export type SearchResult = S['SearchResult']
export type ColumnLineageCounts = S['ColumnLineageCounts']
export type Column = S['Column']
